import { ApiPropertyOptional } from '@nestjs/swagger';
import { IsDateString, IsOptional } from 'class-validator';

// -----------------------------------------------------------------------------
// sisiMove — Expire Journey DTO
// -----------------------------------------------------------------------------
//
// HTTP request body for expiring a Journey.
//
// The following values are intentionally NOT part of this DTO:
// - journeyPublicId → supplied by the route parameter
// - correlationId   → generated by the controller
// - causationId     → application-layer concern
//
// The controller/application layer constructs the ExpireJourneyCommand from
// the validated HTTP input.
//
// -----------------------------------------------------------------------------

export class ExpireJourneyDto {
  // ---------------------------------------------------------------------------
  // Expiration Timestamp
  // ---------------------------------------------------------------------------

  @ApiPropertyOptional({
    example: '2026-08-15T18:00:00.000Z',
    description:
      'Optional effective expiration timestamp. When omitted, the backend uses the current time.',
    format: 'date-time',
  })
  @IsOptional()
  @IsDateString()
  readonly expiredAt?: string;
}
